<script setup lang="ts">
import { dateFormatter } from '@/utils/formatTime'
import request from '@/config/axios'
import download from '@/utils/download'
import * as BoxunExperimentalReportApi from './BoxunExperimentalReportApi'
import BoxunExperimentalReportForm from './BoxunExperimentalReportForm.vue'
import BoxunExperimentalReportDetail from './BoxunExperimentalReportDetail.vue'

type BoxunExperimentalReportRow = Awaited<ReturnType<typeof BoxunExperimentalReportApi.getBoxunExperimentalReportPage>>['list'][number]
type EntityId = string | number

defineOptions({ name: 'BoxunExperimentalReport' })

const message = useMessage()
const { t } = useI18n()
const loading = ref(false)
const total = ref(0)
const rows = ref<BoxunExperimentalReportRow[]>([])
const queryFormRef = ref()
const queryParams = reactive({
  pageNo: 1,
  pageSize: 10,
  commissionNumber: '',
  reportNumber: '',
  projectName: '',
  projectNumber: '',
  engineeringLocation: '',
  sampleNumber: '',
  sampleName: '',
  sampleName4bg: '',
  entrustingUnit: '',
  sgUnit: '',
  jsUnit: '',
  witnessUnit: '',
  representativeBatch: '',
  strengthGrade: '',
  manufacturer: ''
})



const getList = async () => {
  loading.value = true
  try {
    const data = await BoxunExperimentalReportApi.getBoxunExperimentalReportPage(queryParams)
    rows.value = data.list
    total.value = Number(data.total)
  } finally {
    loading.value = false
  }
}

const handleQuery = () => {
  queryParams.pageNo = 1
  getList()
}

const resetQuery = () => {

  queryFormRef.value?.resetFields()

  handleQuery()
}

const formRef = ref()
const openForm = (type: 'create' | 'update', id?: EntityId) => {
  formRef.value?.open(type, id, type === 'create' ? undefined : undefined)
}


const detailRef = ref()
const openDetail = (id: EntityId) => {
  detailRef.value?.open(id)
}



const handleDelete = async (id?: EntityId) => {
  if (id === undefined) return
  await message.delConfirm()
  await BoxunExperimentalReportApi.deleteBoxunExperimentalReport(id)
  message.success(t('common.delSuccess'))
  await getList()
}

const checkedIds = ref<EntityId[]>([])
const handleSelectionChange = (rows: BoxunExperimentalReportRow[]) => {
  checkedIds.value = rows.map((row) => row.id).filter((id): id is EntityId => id !== undefined)
}

const handleDeleteBatch = async () => {
  await message.delConfirm()
  await BoxunExperimentalReportApi.deleteBoxunExperimentalReportList(checkedIds.value)
  message.success(t('common.delSuccess'))
  checkedIds.value = []
  await getList()
}
const exportLoading = ref(false)
const handleExport = async () => {
  await message.exportConfirm()
  exportLoading.value = true
  try {
    const data = await request.download({ url: '/boxun/experimental-report/export-excel', params: queryParams })
    download.excel(data, 'boxunExperimentalReport.xls')
  } finally {
    exportLoading.value = false
  }
}

onMounted(getList)
</script>
